<section class="content-page order-panel"><p class="eyebrow">SİPARİŞ BİLGİSİ</p><h1><?= e($order['order_no']) ?></h1><p>Sipariş durumu: <strong><?= e($order['status']) ?></strong> · Ödeme: <strong><?= e($order['payment_status']) ?></strong></p><h2>Ürünler</h2><?php foreach($orderItems as $item): ?><p><?= e($item['product_name']) ?> × <?= (int)$item['quantity'] ?> — <?= number_format((float)$item['unit_price']*(int)$item['quantity'],2,',','.') ?> ₺</p><?php endforeach; ?><h2>Toplam: <?= number_format((float)$order['total'],2,',','.') ?> ₺</h2><?php if($order['payment_status']!=='paid'): ?><div class="alert">Bu sipariş henüz ödenmedi. Ödeme onayı sağlayıcıdan sunucu tarafında doğrulandığında kod teslimatı başlar.</div><form class="admin-form" method="post" action="<?= e(url('payment/start/'.$order['id'])) ?>"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><label>Telefon<input name="phone" required placeholder="+90 5xx xxx xx xx"></label><label>Adres<input name="address" required minlength="8"></label><label>Şehir<input name="city" required></label><label>Posta kodu<input name="zip" required></label><label>T.C. kimlik numarası (iyzico için)<input name="identity" inputmode="numeric" maxlength="11"></label><label>Ödeme yöntemi<select name="provider" required><option value="">Yöntem seçin</option><?php if(payment_secret('paytr_enabled')==='1'): ?><option value="paytr">PayTR</option><?php endif; ?><?php if(payment_secret('iyzico_enabled')==='1'): ?><option value="iyzico">iyzico</option><?php endif; ?></select></label><button type="submit">Güvenli ödemeye geç</button></form><?php endif; ?><?php if($deliveredCodes||($manualDeliveredCodes??[])): ?><h2>Dijital kodlarınız</h2><?php foreach($deliveredCodes as $code): ?><p class="delivered-code"><?= e(inventory_decrypt($code)) ?></p><?php endforeach; ?><?php foreach(($manualDeliveredCodes??[]) as $code): ?><p class="delivered-code"><?= e(inventory_decrypt($code)) ?></p><?php endforeach; ?><?php endif; ?><?php if($refundRequest): ?><div class="alert">İade talebi durumu: <strong><?= e($refundRequest['status']) ?></strong><?php if(!empty($refundRequest['admin_note'])): ?><p><?= e($refundRequest['admin_note']) ?></p><?php endif; ?></div><?php elseif($order['payment_status']==='paid'&&!$deliveredCodes&&!($manualDeliveredCodes??[])): ?><h2>İade talebi</h2><form class="admin-form" method="post"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="refund_request"><label>İade gerekçesi<textarea name="reason" rows="4" minlength="10" maxlength="3000" required></textarea></label><button type="submit">İade talebi oluştur</button></form><?php endif; ?><a class="primary-link" href="<?= e(url()) ?>">Mağazaya dön</a></section>